CREATE TABLE plugin_metadata(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
INSERT INTO plugin_metadata VALUES(1,1);
CREATE TABLE worker_settings(id INTEGER PRIMARY KEY CHECK(id=1),secret_enc TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,revision INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE worker_nonces(nonce TEXT PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE project_settings(project_id UUID PRIMARY KEY,config JSONB NOT NULL,revision INTEGER NOT NULL DEFAULT 1,needs_reconcile BOOLEAN NOT NULL DEFAULT TRUE,last_error TEXT NOT NULL DEFAULT '',last_reconciled TIMESTAMPTZ);
CREATE TABLE task_rules(project_id UUID NOT NULL,task_id UUID NOT NULL,config JSONB NOT NULL,revision INTEGER NOT NULL DEFAULT 1,base_fingerprint TEXT NOT NULL DEFAULT '',PRIMARY KEY(project_id,task_id));
CREATE TABLE instances(id UUID PRIMARY KEY,project_id UUID NOT NULL,task_id UUID NOT NULL,revision INTEGER NOT NULL,fingerprint TEXT NOT NULL,title TEXT NOT NULL,source JSONB NOT NULL DEFAULT '{}',start_at TIMESTAMPTZ,due_at TIMESTAMPTZ,start_minutes INTEGER NOT NULL,due_minutes INTEGER NOT NULL,freeze_at TIMESTAMPTZ NOT NULL,state TEXT NOT NULL DEFAULT 'active',status_revision INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(project_id,task_id,revision));
CREATE UNIQUE INDEX one_active_instance ON instances(project_id,task_id) WHERE state IN('active','frozen','conflict');
CREATE TABLE grants(id UUID PRIMARY KEY,instance_id UUID NOT NULL REFERENCES instances(id),kind TEXT NOT NULL CHECK(kind IN('start','due')),token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,UNIQUE(instance_id,kind));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,grant_id UUID NOT NULL REFERENCES grants(id),expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE media(id UUID PRIMARY KEY,instance_id UUID NOT NULL REFERENCES instances(id),kind TEXT NOT NULL,object_key TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,bytes BIGINT NOT NULL,mime TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),state TEXT NOT NULL DEFAULT 'temporary');
CREATE TABLE records(id UUID PRIMARY KEY,instance_id UUID NOT NULL REFERENCES instances(id),kind TEXT NOT NULL,media_id UUID NOT NULL UNIQUE REFERENCES media(id),note TEXT NOT NULL DEFAULT '',submitted_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL,op_id TEXT NOT NULL,UNIQUE(instance_id,kind),UNIQUE(instance_id,op_id));
CREATE TABLE outbox(id BIGSERIAL PRIMARY KEY,instance_id UUID NOT NULL REFERENCES instances(id),revision INTEGER NOT NULL,status_id UUID NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_error TEXT NOT NULL DEFAULT '',UNIQUE(instance_id,revision));
CREATE INDEX outbox_ready ON outbox(state,next_attempt);
CREATE TABLE changes(cursor BIGSERIAL PRIMARY KEY,project_id UUID NOT NULL,connection_id TEXT NOT NULL,instance_id UUID NOT NULL REFERENCES instances(id),record_id UUID NOT NULL REFERENCES records(id),revision INTEGER NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE devices(id UUID PRIMARY KEY,project_id UUID NOT NULL,connection_id TEXT NOT NULL,name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE receipts(id UUID PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id),change_cursor BIGINT NOT NULL,op_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'prepared',expected JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(device_id,op_id));
CREATE TABLE conflicts(id UUID PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id),instance_id UUID NOT NULL REFERENCES instances(id),base_revision INTEGER NOT NULL,local JSONB NOT NULL,state TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(device_id,instance_id,base_revision));
